const describeError = (error: unknown) => { if (error instanceof Error) return error.message; if (error && typeof error === 'object') { const item = error as { message?: string; code?: string; details?: string; hint?: string }; return [item.message, item.details, item.hint, item.code ? 'Code ' + item.code : ''].filter(Boolean).join(' · ') || JSON.stringify(error); } return String(error || 'Erreur inconnue'); };
type SectionKey = 'overview' | 'members' | 'timeline' | 'stories' | 'albums' | 'documents' | 'settings';
type Profile = { id: string; first_name: string; last_name: string; post_name?: string | null; nickname?: string | null; display_name?: string; public_slug?: string | null; role?: string; avatar_url?: string | null; background_url?: string | null; background_opacity?: number | null; phone?: string | null; email?: string | null; biography?: string | null; contact_visibility?: VisibilityLevel; website_url?: string | null; instagram_url?: string | null; facebook_url?: string | null; linkedin_url?: string | null; whatsapp_url?: string | null; other_contact?: string | null; family_unit_id?: string | null; is_public?: boolean };
type RecordItem = { id: string; title?: string; name?: string; description?: string | null; content?: string; event_date?: string | null; created_at?: string; visibility?: string }; type ContactPointKind = 'EMAIL' | 'PHONE' | 'WEBSITE' | 'INSTAGRAM' | 'FACEBOOK' | 'LINKEDIN' | 'WHATSAPP' | 'OTHER'; type ContactPoint = { id?: string; kind: ContactPointKind; label: string; value: string; visibility: VisibilityLevel }; function ContactPointIcon({ kind }: { kind: ContactPointKind }) { const icons: Record<ContactPointKind, typeof Mail> = { EMAIL: Mail, PHONE: Phone, WEBSITE: Globe2, INSTAGRAM: Instagram, FACEBOOK: Facebook, LINKEDIN: Linkedin, WHATSAPP: MessageCircle, OTHER: Link2 }; const Icon = icons[kind] || CircleHelp; return <Icon className="size-4" aria-hidden="true" />; }
