function FamilyTree({ members, relationships, pendingInvites, perspectiveId, showPending, onTogglePending, onPerspectiveChange, onInvite, onMemberClick, onInvitationClick }: { members: Profile[]; relationships: any[]; pendingInvites: any[]; perspectiveId: string; showPending: boolean; onTogglePending: () => void; onPerspectiveChange: (id: string) => void; onInvite: () => void; onMemberClick: (member: Profile) => void; onInvitationClick: (invite: any) => void }) {
  const generationMap = new Map<string, number>(); generationMap.set(perspectiveId, 0); let changed = true; while (changed) { changed = false; relationships.forEach(edge => { const from = generationMap.get(edge.from_profile_id); const to = generationMap.get(edge.to_profile_id); if (edge.relationship_type === 'PARENT_OF' || edge.relationship_type === 'GRANDPARENT_OF') { if (from !== undefined && to === undefined) { generationMap.set(edge.to_profile_id, from + 1); changed = true; } if (to !== undefined && from === undefined) { generationMap.set(edge.from_profile_id, to - 1); changed = true; } } else if ((from !== undefined || to !== undefined) && from === undefined) { generationMap.set(edge.from_profile_id, to || 0); changed = true; } else if ((from !== undefined || to !== undefined) && to === undefined) { generationMap.set(edge.to_profile_id, from || 0); changed = true; } }); }
  const rows = new Map<number, Profile[]>(); members.forEach(member => { const generation = generationMap.get(member.id) ?? 0; const row = rows.get(generation) || []; row.push(member); rows.set(generation, row); }); if (showPending) pendingInvites.forEach(invite => { const generation = invite.relationship_type === 'Enfant' ? 1 : invite.relationship_type === 'Parent' || invite.relationship_type === 'Grand-parent' ? -1 : 0; const pseudo = { id: 'invite-' + invite.id, first_name: invite.invitee_first_name, last_name: invite.invitee_last_name, nickname: '', display_name: '', role: invite.role, __pending: true, __invite: invite, __generation: generation }; const row = rows.get(generation) || []; row.push(pseudo as any); rows.set(generation, row); }); const sorted = Array.from(rows.entries()).sort((a,b) => a[0] - b[0]); const label = (member: any) => member.nickname?.trim() ? [member.nickname, member.last_name].filter(Boolean).join(' ') : [member.first_name, member.last_name].filter(Boolean).join(' ') || 'Membre'; return <div className="paper-panel overflow-hidden p-4 md:p-7"><div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div><p className="archive-label">Structure familiale</p><p className="mt-1 text-sm text-ink/55">Les générations et les liens sont positionnés à partir des relations enregistrées.</p></div><div className="flex flex-wrap items-center gap-2"><div className="flex items-center gap-1 border border-ink/10 bg-white/45 p-1" role="listbox" aria-label="Point de vue de l’arbre">{members.slice(0, 12).map(member => <button type="button" role="option" aria-selected={member.id === perspectiveId} key={member.id} onClick={() => onPerspectiveChange(member.id)} className={'px-2 py-1.5 text-[11px] transition ' + (member.id === perspectiveId ? 'bg-ink text-paper' : 'text-ink/55 hover:bg-copper/10 hover:text-ink')}>{member.nickname?.trim() || member.first_name || 'Membre'}</button>)}</div><button type="button" onClick={onTogglePending} aria-pressed={showPending} className={'border px-3 py-2 text-xs transition ' + (showPending ? 'border-copper bg-copper/10 text-copper' : 'border-ink/15 text-ink/60')}>{showPending ? 'Masquer les invitations' : 'Afficher les invitations'}</button><Button onClick={onInvite} className="rounded-none bg-copper text-white hover:bg-copper/90"><Plus className="mr-2 size-4" />Inviter</Button></div></div>{sorted.length ? <div className="relative overflow-x-auto pb-3 no-scrollbar"><div className="min-w-[720px] space-y-8">{sorted.map(([generation, row], rowIndex) => <div key={generation} className="relative"><div className="mb-3 flex items-center gap-3"><span className="h-px flex-1 bg-copper/20" /><span className="text-[10px] uppercase tracking-[0.22em] text-ink/35">Génération {generation}</span><span className="h-px flex-1 bg-copper/20" /></div><div className="flex justify-center gap-5">{row.map((member: any) => <button type="button" onClick={() => member.__pending ? onInvitationClick(member.__invite) : onMemberClick(member)} key={member.id} className={'relative w-48 border p-4 text-center transition ' + (member.__pending ? 'border-copper/50 bg-copper/10 shadow-[0_8px_24px_rgba(157,96,63,.12)]' : 'border-ink/10 bg-white/55')}><div className="mx-auto grid size-14 place-items-center rounded-full border border-copper/30 bg-copper/10 font-display text-lg text-copper">{(label(member).slice(0,2) || '—').toUpperCase()}</div><p className="mt-3 font-display text-xl">{label(member)}</p>{member.__pending && <p className="mt-1 text-xs text-copper">Invitation en attente</p>}</button>)}</div>{rowIndex < sorted.length - 1 && <div className="mx-auto mt-4 h-5 w-px bg-copper/35" />}</div>)}</div></div> : <EmptyState title="L’arbre commence ici" text="Invitez un proche pour créer le premier lien familial." action={<Button onClick={onInvite} className="rounded-none bg-copper text-white hover:bg-copper/90"><Plus className="mr-2 size-4" />Inviter un proche</Button>} />}</div>;
}

